import {specificDiagram} from './diagrams.js';
import {guides} from './content.js';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
function diagram(kind,index){
 const specific=specificDiagram(kind,index);if(specific)return specific;
 if(kind==='world'||kind==='energy')return `<div class="world-seal ${kind}" aria-hidden="true"><i></i><i></i><i></i><span>◇</span></div><p class="diagram-caption">${kind==='world'?'DES MONDES QUI SE RENCONTRENT':'UNE ORIGINE ENCORE OUVERTE'}</p>`;
 if(kind==='roles')return `<div class="role-triad" aria-hidden="true">${['Assaillant','Pilier','Sentinelle'].map((r,i)=>`<div class="${index===i?'active':''}"><span>${['↗','◇','⌖'][i]}</span><strong>${r}</strong></div>`).join('')}</div><p class="diagram-caption">LE RÔLE DONNE UNE FONCTION · LE TYPE DONNE UNE IDENTITÉ</p>`;
 if(kind==='progress')return `<div class="progress-art" aria-hidden="true"><strong>ORA</strong><span>PROTOTYPE</span><div><i></i><i></i><i></i><i></i></div></div><p class="diagram-caption">DES FONDATIONS JOUABLES · UN MATCH COMPLET À CONSOLIDER</p>`;
 return `<div class="tactical-view" data-step="${index}" data-visual="${kind}"><svg viewBox="0 0 600 440" role="img" aria-label="Schéma illustratif de deux camps séparés, avec joueurs, obstacles et une trajectoire de balle"><path class="arena-outline" d="M70 100 150 55H450L530 100V330L450 385H150L70 330Z"/><path class="camp-fill" d="M70 100 150 55H300V385H150L70 330Z"/><path class="center-line" d="M300 55V385"/><path class="upper-zone" d="M150 18H450"/><text x="300" y="12" text-anchor="middle">ZONE SUPÉRIEURE</text><text x="185" y="363" text-anchor="middle">CAMP A</text><text x="415" y="363" text-anchor="middle">CAMP B</text><rect class="goal" x="515" y="165" width="12" height="66" rx="3"/><rect class="obstacle" x="372" y="235" width="22" height="70" rx="2"/><rect class="obstacle" x="192" y="110" width="22" height="60" rx="2"/><path class="ball-path" d="M150 265 280 105 490 285 410 330"/><g class="players"><circle cx="150" cy="265" r="12"/><circle cx="245" cy="320" r="12"/><circle cx="410" cy="330" r="12"/><circle cx="435" cy="130" r="12"/></g><circle class="demo-ball" cx="0" cy="0" r="6"/><circle class="grab-point" cx="240" cy="205" r="7"/></svg></div><p class="diagram-caption">SCHÉMA DE PRINCIPE · MOUVEMENT ILLUSTRATIF</p>`;
}
export function guidePage(path){const g=guides[path];const requested=Number(new URLSearchParams(location.search).get('section'));const i=Number.isInteger(requested)&&requested>=1&&requested<=g.sections.length?requested-1:0;const s=g.sections[i];return `<section class="screen guide-screen" aria-labelledby="screen-title"><div class="guide-heading"><a class="eyebrow" href="${path.startsWith('/univers')?'/univers/':'/jeu/'}">${path.startsWith('/univers')?'ATLAS DES FRAGMENTS':'COMPRENDRE ORA'} ↗</a><h1 id="screen-title" tabindex="-1">${g.title}</h1></div><div class="guide-layout"><nav class="guide-chapters" aria-label="Sujets de ${esc(g.label)}">${g.sections.map((section,n)=>`<a href="${path}/?section=${n+1}" ${n===i?'aria-current="page"':''}><span>${String(n+1).padStart(2,'0')}</span>${section[0]}</a>`).join('')}</nav><article class="guide-reading"><p class="eyebrow">${g.eyebrow}</p><h2>${s[1]}</h2><p class="guide-prose">${s[2]}</p><p class="content-state">${s[3]}</p>${g.visual==='score'&&i===0?`<div class="score-demo"><p class="eyebrow">EXEMPLE DE SCORE EN 2C2</p><output id="score-example" aria-live="polite">0 point · début de séquence</output><div><button data-score="goal">But +5</button><button data-score="hit">Toucher un joueur</button><button data-score="reset" aria-label="Réinitialiser l’exemple">↺</button></div><p class="note">Exemple isolé : les deux touches se suivent avant tout retour.</p></div>`:''}<div class="guide-paging">${i>0?`<a href="${path}/?section=${i}">← Précédent</a>`:'<span></span>'}${i<g.sections.length-1?`<a href="${path}/?section=${i+2}">Suivant →</a>`:'<span>Fin du chapitre</span>'}</div></article><aside class="guide-visual">${diagram(g.visual,i)}</aside></div><nav class="guide-related" aria-label="Poursuivre l’exploration">${g.links.map(([url,title])=>`<a href="${url}">${title} ↗</a>`).join('')}</nav></section>`;}
export function wireGuide(){let points=0,hits=0;document.querySelectorAll('[data-score]').forEach(b=>b.onclick=()=>{let message='début de séquence';if(b.dataset.score==='reset'){points=0;hits=0;}else if(b.dataset.score==='goal'){points+=5;message='but mobile · +5';}else{const added=hits===1?2:1;hits++;points+=added;message=hits===2?'double élimination · +2, retour collectif':'première touche · +1';if(hits===2)hits=0;}document.querySelector('#score-example').textContent=`${points} point${points>1?'s':''} · ${message}`;});}
export function rosterPage(characters,symbols){const role=new URLSearchParams(location.search).get('role')||'Tous';const roles=['Tous','Assaillant','Pilier','Sentinelle'];const selected=roles.includes(role)?role:'Tous';return `<section class="screen roster-screen" aria-labelledby="screen-title"><div class="roster-heading"><p class="eyebrow">NEUF IDENTITÉS / TROIS RÔLES</p><h1 id="screen-title" tabindex="-1">Choisissez votre trajectoire.</h1><p>Des bases de capacités aux identités encore en conception.</p></div><nav class="role-filters" aria-label="Filtrer les personnages">${roles.map(r=>`<a href="/personnages/roster/?role=${r}" ${r===selected?'aria-current="page"':''}>${r==='Tous'?'Tous les rôles':r}</a>`).join('')}</nav><div class="roster-grid">${Object.entries(characters).filter(([,c])=>selected==='Tous'||c.role===selected).map(([key,c])=>`<a class="roster-card" style="--character-color:${c.color}" href="/personnages/${key}/"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${symbols[key]}"/></svg><div><span class="eyebrow">${c.role} / ${c.type}</span><h2>${c.name}</h2><p>${c.state}</p></div><span class="card-arrow" aria-hidden="true">↗</span></a>`).join('')}</div><a class="text-action" href="/jeu/roles/">COMPRENDRE LES RÔLES ET LES ASSOCIATIONS ↗</a></section>`;}
